  def self.mocked_openai_whisper_response(size)
    last_end = 0.0
    segments = (0...size).map do |i|
      start = last_end
      end_time = start + Faker::Number.decimal(l_digits: 2)
      segment = {
        'id' => i,
        'seek' => 0,
        'start' => start,
        'end' => end_time,
        'text' => Faker::Lorem.sentence,
        'tokens' => Array.new(Faker::Number.within(range: 10..50)) { Faker::Lorem.word },
        'temperature' => 0.0,
        'avg_logprob' => Faker::Number.decimal(l_digits: 2),
